window.__OPENSTAX_PHYSICS__[7] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.687Z","number":7,"code":"ch07","slug":"newton-s-law-of-gravitation","title":"Newton's Law of Gravitation","titleVi":"Định Luật Vạn Vật Hấp Dẫn & Định Luật Kepler (Gravitation)","sections":[{"uid":"hsphys.ch07.sec00","moduleId":"m54196","number":"7.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch07.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["What do a falling apple and the orbit of the moon have in common? You will learn in this chapter that each is caused by gravitational force. The motion of all celestial objects, in fact, is determined by the gravitational force, which depends on their mass and separation.","Johannes Kepler discovered three laws of planetary motion that all orbiting planets and moons follow. Years later, Isaac Newton found these laws useful in developing his law of universal gravitation. This law relates gravitational force to the masses of objects and the distance between them. Many years later still, Albert Einstein showed there was a little more to the gravitation story when he published his theory of general relativity."],"figures":[{"sourceId":"imp-id1167067068130","filename":"CNX_HSPhysics_07_00_Kepler.jpg","relativePath":"media/CNX_HSPhysics_07_00_Kepler.jpg","alt":"Two photos show men in old-fashioned dress."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch07.sec01","moduleId":"m54192","number":"7.1","slug":"kepler-s-laws-of-planetary-motion","title":"Kepler's Laws of Planetary Motion","isIntroduction":false,"learningObjectives":["Explain Kepler’s three laws of planetary motion","Apply Kepler’s laws to calculate characteristics of orbits"],"bilingualGuide":{"notebookSummaryVi":"3 Định luật Kepler về chuyển động hành tinh quanh Mặt Trời (Elip, Diện tích quét đều và T²/r³ = const).","wordProblemCues":[{"phraseEn":"Kepler’s third law","meaningVi":"Bình phương chu kỳ tỉ lệ lập phương bán trục lớn","mathNotation":"T₁²/T₂² = r₁³/r₂³"}],"commonTrapsVi":["r là khoảng cách từ TÂM đến TÂM của hai thiên thể (không phải độ cao tính từ mặt đất!)."]},"keyEquations":[{"name":"Kepler’s third law","formula":"\\(\\frac{{T}_{1}^{2}}{{T}_{2}^{2}} = \\frac{{r}_{1}^{3}}{{r}_{2}^{3}}\\)"},{"name":"eccentricity","formula":"\\(e = \\frac{f}{a}\\)"},{"name":"area of an ellipse","formula":"\\(A = \\pi ab\\)"},{"name":"semi-major axis of an ellipse","formula":"\\(a = ({r}_{\\text{a}} + {r}_{\\text{p}})/2\\)"},{"name":"semi-minor axis of an ellipse","formula":"\\(b = \\sqrt{{r}_{\\text{a}}{r}_{\\text{p}}}\\)"}],"subsections":[{"uid":"hsphys.ch07.sec01.sub01","title":"Concepts Related to Kepler’s Laws of Planetary Motion","summaryVi":null,"paragraphs":["Examples of orbits abound. Hundreds of artificial satellites orbit Earth together with thousands of pieces of debris. The moon’s orbit around Earth has intrigued humans from time immemorial. The orbits of planets, asteroids, meteors, and comets around the sun are no less interesting. If we look farther, we see almost unimaginable numbers of stars, galaxies, and other celestial objects orbiting one another and interacting through gravity.","All these motions are governed by gravitational force. The orbital motions of objects in our own solar system are simple enough to describe with a few fairly simple laws. The orbits of planets and moons satisfy the following two conditions:","Based on the motion of the planets about the sun, Kepler devised a set of three classical laws, called Kepler’s laws of planetary motion , that describe the orbits of all bodies satisfying these two conditions:","These descriptive laws are named for the German astronomer Johannes Kepler (1571–1630). He devised them after careful study (over some 20 years) of a large amount of meticulously recorded observations of planetary motion done by Tycho Brahe (1546–1601). Such careful collection and detailed recording of methods and data are hallmarks of good science. Data constitute the evidence from which new interpretations and meanings can be constructed. Let’s look closer at each of these laws.","The orbit of each planet about the sun is an ellipse with the sun at one focus, as shown in [Figure 7.1]. The planet’s closest approach to the sun is called perihelion and its farthest distance from the sun is called aphelion .","If you know the aphelion ( r a ) and perihelion ( r p ) distances, then you can calculate the semi-major axis ( a ) and semi-minor axis ( b )."],"figures":[{"sourceId":"fs-id1167065872487","filename":"CNX_HSPhysics_07_01_circle.jpg","relativePath":"media/CNX_HSPhysics_07_01_circle.jpg","alt":"Three ellipses are shown. In image (a) the ellipse is divided into quadrants. In image (b) the sun and a planet are shown. In image (c), the sun and planet are shown, and the aphelion and perihelion."},{"sourceId":"fs-id1167065711167","filename":"CNX_HSPhysics_07_01_pen.jpg","relativePath":"media/CNX_HSPhysics_07_01_pen.jpg","alt":"A picture shows a hand holding a pen, drawing a blue ellipse, with 2 black pins inside the ellipse. A red string is attached to the pins. The pen is held inside the red string, to draw the ellipse."}],"tables":[]},{"uid":"hsphys.ch07.sec01.sub02","title":"Kepler’s Second Law","summaryVi":null,"paragraphs":["Each planet moves so that an imaginary line drawn from the sun to the planet sweeps out equal areas in equal times, as shown in [Figure 7.1]."],"figures":[{"sourceId":"fs-id1167065891604","filename":"CNX_HSPhysics_07_01_planet.jpg","relativePath":"media/CNX_HSPhysics_07_01_planet.jpg","alt":"A diagram shows a circle, divided into quadrants. The sun (labeled M) is inside the circle. The circle represents a planet’s orbit around the sun. The planet is labeled m. Shaded regions are labeled A1, A2, and A3"}],"tables":[]},{"uid":"hsphys.ch07.sec01.sub03","title":"Kepler’s Third Law","summaryVi":null,"paragraphs":["The ratio of the periods squared of any two planets around the sun is equal to the ratio of their average distances from the sun cubed. In equation form, this is","where T is the period (time for one orbit) and r is the average distance (also called orbital radius). This equation is valid only for comparing two small masses orbiting a single large mass. Most importantly, this is only a descriptive equation; it gives no information about the cause of the equality.","This simulation allows you to create your own solar system so that you can see how changing distances and masses determines the orbits of planets. Click Help for instructions."],"figures":[],"tables":[]},{"uid":"hsphys.ch07.sec01.sub04","title":"Calculations Related to Kepler’s Laws of Planetary Motion","summaryVi":null,"paragraphs":["Refer back to [Figure 7.1] (a) . Notice which distances are constant. The foci are fixed, so distance \\(\\bar{{f}_{1}{f}_{2}}\\) is a constant. The definition of an ellipse states that the sum of the distances \\(\\bar{{f}_{1}m} + \\bar{m{f}_{2}}\\) is also constant. These two facts taken together mean that the perimeter of triangle \\(\\Delta {f}_{1}m{f}_{2}\\) must also be constant. Knowledge of these constants will help you determine positions and distances of objects in a system that includes one object orbiting another."],"figures":[],"tables":[]},{"uid":"hsphys.ch07.sec01.sub05","title":"Kepler’s Second Law","summaryVi":null,"paragraphs":["Refer back to [Figure 7.1]. The second law says that the segments have equal area and that it takes equal time to sweep through each segment. That is, the time it takes to travel from A to B equals the time it takes to travel from C to D, and so forth. Velocity v equals distance d divided by time t : \\(\\mathbf{v} = d/t\\) . Then, \\(t = d/\\mathbf{v}\\), so distance divided by velocity is also a constant. For example, if we know the average velocity of Earth on June 21 and December 21, we can compare the distance Earth travels on those days.","The degree of elongation of an elliptical orbit is called its eccentricity ( e ). Eccentricity is calculated by dividing the distance f from the center of an ellipse to one of the foci by half the long axis a .","When \\(e = 0\\), the ellipse is a circle.","The area of an ellipse is given by \\(A = \\pi ab\\), where b is half the short axis. If you know the axes of Earth’s orbit and the area Earth sweeps out in a given period of time, you can calculate the fraction of the year that has elapsed."],"figures":[],"tables":[]},{"uid":"hsphys.ch07.sec01.sub06","title":"Kepler’s Third Law","summaryVi":null,"paragraphs":["Kepler’s third law states that the ratio of the squares of the periods of any two planets ( T 1 , T 2 ) is equal to the ratio of the cubes of their average orbital distance from the sun ( r 1 , r 2 ). Mathematically, this is represented by","From this equation, it follows that the ratio r 3 /T 2 is the same for all planets in the solar system. Later we will see how the work of Newton leads to a value for this constant."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch07.sec01.ex01","number":"7.1.1","title":"Kepler’s First Law","problem":"At its closest approach, a moon comes within 200,000 km of the planet it orbits. At that point, the moon is 300,000 km from the other focus of its orbit, f 2 . The planet is focus f 1 of the moon’s elliptical orbit. How far is the moon from the planet when it is 260,000 km from f 2 ?","problemImages":[],"strategy":"Show and label the ellipse that is the orbit in your solution. Picture the triangle f 1 m f 2 collapsed along the major axis and add up the lengths of the three sides. Find the length of the unknown side of the triangle when the moon is 260,000 km from f 2 .","solution":"Perimeter of \\({f}_{1}m{f}_{2} = 200,000\\,\\text{km} + 100,000\\,\\text{km} + 300,000\\,\\text{km} = 600,000\\,\\text{km.}\\)\n\\(m{f}_{1} = 600,000\\,\\text{km} - (100,000\\,\\text{km} + 260,000\\,\\text{km}) = 240,000\\,\\text{km.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The perimeter of triangle f 1 mf 2 must be constant because the distance between the foci does not change and Kepler’s first law says the orbit is an ellipse. For any ellipse, the sum of the two sides of the triangle, which are f 1 m and mf 2 , is constant."},{"uid":"hsphys.ch07.sec01.ex02","number":"7.1.2","title":"Kepler’s Second Law","problem":"[Figure 7.1] shows the major and minor axes of an ellipse. The semi-major and semi-minor axes are half of these, respectively.\nThe major axis is the length of the ellipse, and the minor axis is the width of the ellipse. The semi-major axis is half the major axis, and the semi-minor axis is half the minor axis. Earth’s orbit is very slightly elliptical, with a semi-major axis of 1.49598 × 10 8 km and a semi-minor axis of 1.49577 × 10 8 km. If Earth’s period is 365.26 days, what area does an Earth-to-sun line sweep past in one day?","problemImages":[{"sourceId":"fs-id1167066155692","filename":"CNX_HSPhysics_07_01_ellipse.jpg","relativePath":"media/CNX_HSPhysics_07_01_ellipse.jpg","alt":"A drawing shows as ellipse, divided into quadrants. The horizontal line is labeled major axis; the vertical line is labeled minor axis. A focus point is marked at each end of the major axis."}],"strategy":"Each day, Earth sweeps past an equal-sized area, so we divide the total area by the number of days in a year to find the area swept past in one day. For total area use \\(A = \\pi ab\\) . Calculate A , the area inside Earth’s orbit and divide by the number of days in a year (i.e., its period).","solution":"\\(\\text{area per day} = \\frac{\\text{total area}}{\\text{total number of days}} = \\frac{\\pi ab}{\\text{365 d}} = \\frac{\\pi (1.496 \\times {10}^{8}\\text{km})(1.496 \\times {10}^{3}\\text{km})}{\\text{365 d}} = 1.93 \\times {10}^{14}{\\text{km}}^{2}/\\text{d}\\)\nThe area swept out in one day is thus \\(1.93 \\times {10}^{14}{\\text{km}}^{\\text{2}}\\) .","solutionImages":[],"solutionTables":[],"discussion":"The answer is based on Kepler’s law, which states that a line from a planet to the sun sweeps out equal areas in equal times."},{"uid":"hsphys.ch07.sec01.ex03","number":"7.1.3","title":"Kepler’s Third Law","problem":"Given that the moon orbits Earth each 27.3 days and that it is an average distance of \\(3.84 \\times {10}^{8}\\text{m}\\) from the center of Earth, calculate the period of an artificial satellite orbiting at an average altitude of 1,500 km above Earth’s surface.","problemImages":[],"strategy":"The period, or time for one orbit, is related to the radius of the orbit by Kepler’s third law, given in mathematical form by \\(\\frac{{T}_{1}^{2}}{{T}_{2}^{2}} = \\frac{{r}_{1}^{3}}{{r}_{2}^{3}}\\). Let us use the subscript 1 for the moon and the subscript 2 for the satellite. We are asked to find T 2 . The given information tells us that the orbital radius of the moon is \\({r}_{1} = 3.84 \\times {10}^{8}\\text{m}\\), and that the period of the moon is \\({T}_{1} = 27.3\\,\\text{days}\\) . The height of the artificial satellite above Earth’s surface is given, so to get the distance r 2 from the center of Earth we must add the height to the radius of Earth (6380 km). This gives \\({r}_{2} = 1500\\,\\text{km} + 6380\\,\\text{km} = 7880\\,\\text{km}\\) . Now all quantities are known, so T 2 can be found.","solution":"To solve for T 2 , we cross-multiply and take the square root, yielding\n\\({T}_{2}^{2} = {T}_{1}^{2}{(\\frac{{r}_{2}}{{r}_{1}})}^{3};{T}_{2} = {T}_{1}{(\\frac{{r}_{2}}{{r}_{1}})}^{\\frac{3}{2}}{T}_{2} = (27.3\\text{d})(\\frac{24.0\\text{h}}{\\text{d}}){(\\frac{7880\\text{km}}{3.84 \\times {10}^{5}\\text{km}})}^{\\frac{3}{2}} = 1.93\\text{h}.\\)","solutionImages":[],"solutionTables":[],"discussion":"This is a reasonable period for a satellite in a fairly low orbit. It is interesting that any satellite at this altitude will complete one orbit in the same amount of time."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch07.sec01.feat01","type":"tip","title":"Tips for Success","text":"Note that while, for historical reasons, Kepler’s laws are stated for planets orbiting the sun, they are actually valid for all bodies satisfying the two previously stated conditions.","images":[]},{"uid":"hsphys.ch07.sec01.feat02","type":"physics-in-action","title":"History: Ptolemy vs. Copernicus","text":"Before the discoveries of Kepler, Copernicus, Galileo, Newton, and others, the solar system was thought to revolve around Earth as shown in [Figure 7.1] (a) . This is called the Ptolemaic model , named for the Greek philosopher Ptolemy who lived in the second century AD. The Ptolemaic model is characterized by a list of facts for the motions of planets, with no explanation of cause and effect. There tended to be a different rule for each heavenly body and a general lack of simplicity.\n[Figure 7.1] (b) represents the modern or Copernican model . In this model, a small set of rules and a single underlying force explain not only all planetary motion in the solar system, but also all other situations involving gravity. The breadth and simplicity of the laws of physics are compelling.\n(a) The Ptolemaic model of the universe has Earth at the center with the moon, the planets, the sun, and the stars revolving about it in complex circular paths. This geocentric (Earth-centered) model, which can be made progressively more accurate by adding more circles, is purely descriptive, containing no hints about the causes of these motions. (b) The Copernican heliocentric (sun-centered) model is a simpler and more accurate model. Nicolaus Copernicus (1473–1543) first had the idea that the planets circle the sun, in about 1514. It took him almost 20 years to work out the mathematical details for his model. He waited another 10 years or so to publish his work. It is thought he hesitated because he was afraid people would make fun of his theory. Actually, the reaction of many people was more one of fear and anger. Many people felt the Copernican model threatened their basic belief system. About 100 years later, the astronomer Galileo was put under house arrest for providing evidence that planets, including Earth, orbited the sun. In all, it took almost 300 years for everyone to admit that Copernicus had been right all along.\nExplain why Earth does actually appear to be the center of the solar system.\nEarth appears to be the center of the solar system because Earth is at the center of the universe, and everything revolves around it in a circular orbit.\nEarth appears to be the center of the solar system because, in the reference frame of Earth, the sun, moon, and planets all appear to move across the sky as if they were circling Earth.\nEarth appears to be at the center of the solar system because Earth is at the center of the solar system and all the heavenly bodies revolve around it.\nEarth appears to be at the center of the solar system because Earth is located at one of the foci of the elliptical orbit of the sun, moon, and other planets.","images":[{"sourceId":"fs-id1167065849651","filename":"CNX_HSPhysics_07_01_solar.jpg","relativePath":"media/CNX_HSPhysics_07_01_solar.jpg","alt":"Image a shows the Ptolemaic view of the solar system. This view shows Earth at the center of the solar system with all other planets orbiting clockwise, the moon circling the Earth, Mercury and Venus which go in wide circles as it orbits, which are called Epicycles. The Sun orbits earth between Venus and Mars. Mars circles opposite of the others, its own path shown with a looping arrow. Jupiter and Saturn come next. On the outside of the solar system are stars. Image b shows the Copernican view of the solar system which is the more traditional view of the solar system with the Sun in the center and the other planets orbiting the sun."}]}],"summaryPoints":["All satellites follow elliptical orbits.","The line from the satellite to the parent body sweeps out equal areas in equal time.","The radius cubed divided by the period squared is a constant for all satellites orbiting the same parent body."],"glossary":[{"term":"aphelion","termVi":"Điểm viễn nhật","definition":"the point farthest from the sun in the path of an orbiting planet (called apoapsis for other celestial bodies)","definitionVi":"Điểm xa Mặt Trời nhất trên quỹ đạo elip của hành tinh.","memoryTipVi":"A-phelion = Away (xa Mặt Trời nhất, chuyển động chậm nhất)."},{"term":"Copernican model","termVi":"Mô hình nhật tâm (Copernicus)","definition":"the model of the solar system where the sun is at the center of the solar system and all the planets orbit around it; this is also called the heliocentric model","definitionVi":"Mô hình đặt Mặt Trời ở trung tâm, các hành tinh quay quanh Mặt Trời.","memoryTipVi":"Đúng với thực tế thiên văn."},{"term":"eccentricity","termVi":"Độ lệch tâm (e)","definition":"a measure of the separation of the foci of an ellipse","definitionVi":"Thước đo mức độ dẹt của hình elip (e = 0 là đường tròn hoàn hảo).","memoryTipVi":"Quỹ đạo Trái Đất có e ≈ 0.017 (gần như tròn)."},{"term":"Kepler’s laws of planetary motion","termVi":"3 Định luật Kepler về chuyển động hành tinh","definition":"three laws derived by Johannes Kepler that describe the properties of all orbiting satellites","definitionVi":"(1) Quỹ đạo elip; (2) Bán kính quét diện tích bằng nhau trong thời gian bằng nhau; (3) T² ∝ r³.","memoryTipVi":"Định luật 3: (T₁/T₂)² = (r₁/r₂)³."},{"term":"perihelion","termVi":"Điểm cận nhật","definition":"closest distance between a planet and the sun (called periapsis for other celestial bodies)","definitionVi":"Điểm gần Mặt Trời nhất trên quỹ đạo elip của hành tinh.","memoryTipVi":"Tại cận nhật, hành tinh chuyển động NHANH NHẤT."},{"term":"Ptolemaic model","termVi":"Mô hình địa tâm (Ptolemy)","definition":"the model of the solar system where Earth is at the center of the solar system and the sun and all the planets orbit around it; this is also called the geocentric model","definitionVi":"Mô hình cổ đại cho rằng Trái Đất đứng yên ở trung tâm vũ trụ.","memoryTipVi":"Đã bị thay thế bởi mô hình Nhật tâm."}],"assessments":[{"uid":"hsphys.ch07.sec01.q002","sourceId":"fs-id1167064899735","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or false—According to Keplers laws of planetary motion, a satellite increases its speed as it approaches its parent body and decreases its speed as it moves away from the parent body.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q004","sourceId":"fs-id1167064979336","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A planet with no axial tilt is located in another solar system. It circles its sun in a very elliptical orbit so that the temperature varies greatly throughout the year. If the year there has 612 days and the inhabitants celebrate the coldest day on day 1 of their calendar, when is the warmest day?","images":[],"choices":[{"label":"a","text":"Day 1"},{"label":"b","text":"Day 153"},{"label":"c","text":"Day 306"},{"label":"d","text":"Day 459"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q006","sourceId":"fs-id1167064953077","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A circle is a special case of an ellipse. Explain how a circle is different from other ellipses.","images":[],"choices":[{"label":"a","text":"The foci of a circle are at the same point and are located at the center of the circle."},{"label":"b","text":"The foci of a circle are at the same point and are located at the circumference of the circle."},{"label":"c","text":"The foci of a circle are at the same point and are located outside of the circle."},{"label":"d","text":"The foci of a circle are at the same point and are located anywhere on the diameter, except on its midpoint."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q007","sourceId":"eip-id1166847409671","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Comets have very elongated elliptical orbits with the sun at one focus. Using Kepler's Law, explain why a comet travels much faster near the sun than it does at the other end of the orbit.","images":[],"choices":[{"label":"a","text":"Because the satellite sweeps out equal areas in equal times"},{"label":"b","text":"Because the satellite sweeps out unequal areas in equal times"},{"label":"c","text":"Because the satellite is at the other focus of the ellipse"},{"label":"d","text":"Because the square of the period of the satellite is proportional to the cube of its average distance from the sun"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q008","sourceId":"eip-id1166850087786","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or False—A planet-satellite system must be isolated from other massive objects to follow Keplers laws of planetary motion.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q010","sourceId":"fs-id1167066091131","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"In the figure, the time it takes for the planet to go from A to B, C to D, and E to F is the same.\nCompare the areas A 1 , A 2 , and A 3 in terms of size.","images":[{"sourceId":"fs-id1169831275315","filename":"CNX_HSPhysics_07_01_planet.jpg","relativePath":"media/CNX_HSPhysics_07_01_planet.jpg","alt":"A diagram shows a circle, divided into quadrants. The sun (labeled M) is inside the circle. The circle represents a planet’s orbit around the sun. The planet is labeled m. Shaded regions are labeled A1, A2, and A3"}],"choices":[{"label":"a","text":"A 1 ≠ A 2 ≠ A 3"},{"label":"b","text":"A 1 = A 2 = A 3"},{"label":"c","text":"A 1 = A 2 > A 3"},{"label":"d","text":"A 1 > A 2 = A 3"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q011","sourceId":"eip-id1166849880392","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"A moon orbits a planet in an elliptical orbit. The foci of the ellipse are 50, 000 km apart. The closest approach of the moon to the planet is 400, 000 km. What is the length of the major axis of the orbit?","images":[],"choices":[{"label":"a","text":"400, 000 km"},{"label":"b","text":"450, 000, km"},{"label":"c","text":"800, 000 km"},{"label":"d","text":"850, 000 km"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q012","sourceId":"eip-id1166850023538","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"In this figure, if f 1 represents the parent body, which set of statements holds true?","images":[{"sourceId":"fs-id1169830619088","filename":"CNX_HSPhysics_07_01_kep.jpg","relativePath":"media/CNX_HSPhysics_07_01_kep.jpg","alt":"The image shows an oval with small irregular pie shapes shaded in. The left smaller pie shape is labeled X and the right skinny pie shape is labeled Y."}],"choices":[{"label":"a","text":"Area X < Area Y; the speed is greater for area X."},{"label":"b","text":"Area X > Area Y; the speed is greater for area Y."},{"label":"c","text":"Area X = Area Y; the speed is greater for area X."},{"label":"d","text":"Area X = Area Y; the speed is greater for area Y."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q013","sourceId":"fs-id1167064979336","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A planet with no axial tilt is located in another solar system. It circles its sun in a very elliptical orbit so that the temperature varies greatly throughout the year. If the year there has 612 days and the inhabitants celebrate the coldest day on day 1 of their calendar, when is the warmest day?","images":[],"choices":[{"label":"a","text":"Day 1"},{"label":"b","text":"Day 153"},{"label":"c","text":"Day 306"},{"label":"d","text":"Day 459"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q015","sourceId":"fs-id1167066097209","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The closest Earth comes to the sun is 1.47×10 8 km, and Earths farthest distance from the sun is 1.52×10 8 km. What is the area inside Earths orbit?","images":[],"choices":[{"label":"a","text":"2.23×10 16 km 2"},{"label":"b","text":"6.79×10 16 km 2"},{"label":"c","text":"7.02×10 16 km 2"},{"label":"d","text":"7.26×10 16 km 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q016","sourceId":"fs-id1167065742906","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Earth is 1.496×10 8 km from the sun, and Neptune is 4.490×10 9 km from the sun. What best represents the number of Earth years it takes for Neptune to complete one orbit around the sun?","images":[],"choices":[{"label":"a","text":"10 years"},{"label":"b","text":"30 years"},{"label":"c","text":"160 years"},{"label":"d","text":"900 years"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q017","sourceId":"fs-id1167064894605","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A planet of mass m circles a sun of mass M. Which distance changes throughout the planet’s orbit?","images":[],"choices":[{"label":"a","text":"\\(\\bar{{f}_{1}{f}_{2}}\\)"},{"label":"b","text":"\\(\\bar{mM}\\)"},{"label":"c","text":"\\(\\bar{M{f}_{2}}\\)"},{"label":"d","text":"\\(\\bar{M{f}_{1}}\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q019","sourceId":"eip-id1166851384887","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"An artificial satellite orbits the Earth at a distance of 1.45×10 4 km from Earths center. The moon orbits the Earth at a distance of 3.84×10 5 km once every 27.3 days. How long does it take the satellite to orbit the Earth?","images":[],"choices":[{"label":"a","text":"0.200 days"},{"label":"b","text":"3.07 days"},{"label":"c","text":"243 days"},{"label":"d","text":"3721 days"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q020","sourceId":"eip-id1166849856717","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Earth is 1.496×10 8 km from the sun, and Venus is 1.08×10 8 km from the sun. One day on Venus is 243 Earth days long. What best represents the number of Venusian days in a Venusian year?","images":[],"choices":[{"label":"a","text":"0.78 days"},{"label":"b","text":"0.92 days"},{"label":"c","text":"1.08 days"},{"label":"d","text":"1.21 days"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q025","sourceId":"fs-id1167064819285","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The orbit of Halley's Comet has an eccentricity of 0.967 and stretches to the edge of the solar system.\nPart A. Describe the shape of the comets orbit.\nPart B. Compare the distance traveled per day when it is near the sun to the distance traveled per day when it is at the edge of the solar system.\nPart C. Describe variations in the comet's speed as it completes an orbit. Explain the variations in terms of Kepler's second law of planetary motion.","images":[],"choices":[{"label":"a","text":"Part A. The orbit is circular, with the sun at the center. Part B. The comet travels much farther when it is near the sun than when it is at the edge of the solar system. Part C. The comet decelerates as it approaches the sun and accelerates as it leaves the sun."},{"label":"b","text":"Part A. The orbit is circular, with the sun at the center. Part B. The comet travels much farther when it is near the sun than when it is at the edge of the solar system. Part C. The comet accelerates as it approaches the sun and decelerates as it leaves the sun."},{"label":"c","text":"Part A. The orbit is very elongated, with the sun near one end. Part B. The comet travels much farther when it is near the sun than when it is at the edge of the solar system. Part C. The comet decelerates as it approaches the sun and accelerates as it moves away from the sun."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec01.q026","sourceId":"fs-id1167064906921","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"For convenience, astronomers often use astronomical units (AU) to measure distances within the solar system. One AU equals the average distance from Earth to the sun. Halleys Comet returns once every 75.3 years. What is the average radius of the orbit of Halleys Comet in AU?","images":[],"choices":[{"label":"a","text":"0.002 AU"},{"label":"b","text":"0.056 AU"},{"label":"c","text":"17.8 AU"},{"label":"d","text":"653 AU"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":5,"subsectionCount":6,"workedExampleCount":3,"snapLabCount":0,"glossaryCount":6,"assessmentCount":16}},{"uid":"hsphys.ch07.sec02","moduleId":"m54189","number":"7.2","slug":"newton-s-law-of-universal-gravitation-and-einstein-s-theory-of-general-relativity","title":"Newton's Law of Universal Gravitation and Einstein's Theory of General Relativity","isIntroduction":false,"learningObjectives":["Explain Newton’s law of universal gravitation and compare it to Einstein’s theory of general relativity","Perform calculations using Newton’s law of universal gravitation"],"bilingualGuide":{"notebookSummaryVi":"Định luật Vạn vật hấp dẫn Newton (F = Gm₁m₂/r²) và cái nhìn của Thuyết tương đối rộng Einstein về độ cong không–thời gian.","wordProblemCues":[{"phraseEn":"inverse-square law","meaningVi":"Khoảng cách tăng 2 lần → Lực hấp dẫn giảm 4 lần","mathNotation":"F ∝ 1/r²"}],"commonTrapsVi":["Không nhầm hằng số hấp dẫn G = 6.67×10⁻¹¹ với gia tốc trọng trường g = 9.8 m/s²!"]},"keyEquations":[{"name":"Newton’s second law of motion","formula":"\\(\\mathbf{F} = m\\mathbf{a} = m\\mathbf{g}\\)"},{"name":"Newton’s universal law of gravitation","formula":"\\(\\mathbf{F} = G\\frac{mM}{{r}^{2}}\\)"},{"name":"acceleration due to gravity","formula":"\\(\\mathbf{g} = G\\frac{M}{{r}^{2}}\\)"},{"name":"constant for satellites orbiting the same massive object","formula":"\\(\\frac{{r}^{3}}{{T}^{2}} = \\frac{GM}{4{\\pi}^{2}}\\)"}],"subsections":[{"uid":"hsphys.ch07.sec02.sub01","title":"Concepts Related to Newton’s Law of Universal Gravitation","summaryVi":null,"paragraphs":["Sir Isaac Newton was the first scientist to precisely define the gravitational force, and to show that it could explain both falling bodies and astronomical motions. See [Figure 7.2]. But Newton was not the first to suspect that the same force caused both our weight and the motion of planets. His forerunner, Galileo Galilei, had contended that falling bodies and planetary motions had the same cause. Some of Newton’s contemporaries, such as Robert Hooke, Christopher Wren, and Edmund Halley, had also made some progress toward understanding gravitation. But Newton was the first to propose an exact mathematical form and to use that form to show that the motion of heavenly bodies should be conic sections—circles, ellipses, parabolas, and hyperbolas. This theoretical prediction was a major triumph. It had been known for some time that moons, planets, and comets follow such paths, but no one had been able to propose an explanation of the mechanism that caused them to follow these paths and not others.","The gravitational force is relatively simple. It is always attractive, and it depends only on the masses involved and the distance between them. Expressed in modern language, Newton’s universal law of gravitation states that every object in the universe attracts every other object with a force that is directed along a line joining them. The force is directly proportional to the product of their masses and inversely proportional to the square of the distance between them. This attraction is illustrated by [Figure 7.2].","For two bodies having masses m and M with a distance r between their centers of mass, the equation for Newton’s universal law of gravitation is","where F is the magnitude of the gravitational force and G is a proportionality factor called the gravitational constant . G is a universal constant, meaning that it is thought to be the same everywhere in the universe. It has been measured experimentally to be \\(G = 6.673 \\times {10}^{- 11}\\text{N} \\cdot {\\text{m}}^{\\text{2}}{\\text{/kg}}^{\\text{2}}\\) .","If a person has a mass of 60.0 kg, what would be the force of gravitational attraction on him at Earth’s surface? G is given above, Earth’s mass M is 5.97 × 10 24 kg, and the radius r of Earth is 6.38 × 10 6 m. Putting these values into Newton’s universal law of gravitation gives","We can check this result with the relationship: \\(\\mathbf{F} = m\\mathbf{g} = (60\\,\\text{kg})(9.8{\\text{m/s}}^{2}) = 588\\,\\text{N}\\)","You may remember that g , the acceleration due to gravity, is another important constant related to gravity. By substituting g for a in the equation for Newton’s second law of motion we get \\(\\mathbf{F} = m\\mathbf{g}\\) . Combining this with the equation for universal gravitation gives","Cancelling the mass m on both sides of the equation and filling in the values for the gravitational constant and mass and radius of the Earth, gives the value of g, which may look familiar.","This is a good point to recall the difference between mass and weight. Mass is the amount of matter in an object; weight is the force of attraction between the mass within two objects. Weight can change because g is different on every moon and planet. An object’s mass m does not change but its weight m g can.","Move the sun, Earth, moon and space station in this simulation to see how it affects their gravitational forces and orbital paths. Visualize the sizes and distances between different heavenly bodies. Turn off gravity to see what would happen without it!","It is possible to derive Kepler’s third law from Newton’s law of universal gravitation. Applying Newton’s second law of motion to angular motion gives an expression for centripetal force, which can be equated to the expression for force in the universal gravitation equation. This expression can be manipulated to produce the equation for Kepler’s third law. We saw earlier that the expression r 3 /T 2 is a constant for satellites orbiting the same massive object. The derivation of Kepler’s third law from Newton’s law of universal gravitation and Newton’s second law of motion yields that constant:","where M is the mass of the central body about which the satellites orbit (for example, the sun in our solar system). The usefulness of this equation will be seen later.","The universal gravitational constant G is determined experimentally. This determination was first done accurately in 1798 by English scientist Henry Cavendish (1731–1810), more than 100 years after Newton published his universal law of gravitation. The measurement of G is very basic and important because it determines the strength of one of the four forces in nature. Cavendish’s experiment was very difficult because he measured the tiny gravitational attraction between two ordinary-sized masses (tens of kilograms at most) by using an apparatus like that in [Figure 7.2]. Remarkably, his value for G differs by less than 1% from the modern value.","Einstein’s theory of general relativity explained some interesting properties of gravity not covered by Newton’s theory. Einstein based his theory on the postulate that acceleration and gravity have the same effect and cannot be distinguished from each other. He concluded that light must fall in both a gravitational field and in an accelerating reference frame. [Figure 7.2] shows this effect (greatly exaggerated) in an accelerating elevator. In [Figure 7.2] (a) , the elevator accelerates upward in zero gravity. In [Figure 7.2] (b) , the room is not accelerating but is subject to gravity. The effect on light is the same: it “falls” downward in both situations. The person in the elevator cannot tell whether the elevator is accelerating in zero gravity or is stationary and subject to gravity. Thus, gravity affects the path of light, even though we think of gravity as acting between masses, while photons are massless.","Einstein’s theory of general relativity got its first verification in 1919 when starlight passing near the sun was observed during a solar eclipse. (See [Figure 7.2].) During an eclipse, the sky is darkened and we can briefly see stars. Those on a line of sight nearest the sun should have a shift in their apparent positions. Not only was this shift observed, but it agreed with Einstein’s predictions well within experimental uncertainties. This discovery created a scientific and public sensation. Einstein was now a folk hero as well as a very great scientist. The bending of light by matter is equivalent to a bending of space itself, with light following the curve. This is another radical change in our concept of space and time. It is also another connection that any particle with mass or energy (e.g., massless photons) is affected by gravity.","To summarize the two views of gravity, Newton envisioned gravity as a tug of war along the line connecting any two objects in the universe. In contrast, Einstein envisioned gravity as a bending of space-time by mass.","NASA’s Gravity Probe B (GP-B) mission has confirmed two key predictions derived from Albert Einstein’s general theory of relativity. The probe, shown in [Figure 7.2] was launched in 2004. It carried four ultra-precise gyroscopes designed to measure two effects hypothesized by Einstein’s theory:","Both effects were measured with unprecedented precision. This was done by pointing the gyroscopes at a single star while orbiting Earth in a polar orbit. As predicted by relativity theory, the gyroscopes experienced very small, but measureable, changes in the direction of their spin caused by the pull of Earth’s gravity.","The principle investigator suggested imagining Earth spinning in honey. As Earth rotates it drags space and time with it as it would a surrounding sea of honey."],"figures":[{"sourceId":"fs-id1167066793712","filename":"CNX_HSPhysics_07_02_apple.jpg","relativePath":"media/CNX_HSPhysics_07_02_apple.jpg","alt":"A painting shows a man sitting under a tree, from which an apple is falling."},{"sourceId":"fs-id1167067032646","filename":"CNX_HSPhysics_07_02_gravity.jpg","relativePath":"media/CNX_HSPhysics_07_02_gravity.jpg","alt":"A figure shows a small circle and a large circle. A black line goes from one circle to the other. A red line with an arrow extends outward from each circle. The red lines have arrows on one end, pointing away from the circles, towards the midpoint of the space in between the circles."},{"sourceId":"fs-id1167066809101","filename":"CNX_HSPhysics_07_02_sphere.jpg","relativePath":"media/CNX_HSPhysics_07_02_sphere.jpg","alt":"Apparatus consisting of two large spheres, one on each end of a horizontal rod centered on a pivot. Two smaller spheres are at the extremity of a smaller horizontal rod also centered on same pivot point. Light source shines laser beam that hits mirror and reflects onto scale to show pivot angle of spheres."},{"sourceId":"fs-id1167067300278","filename":"CNX_HSPhysics_07_02_light.jpg","relativePath":"media/CNX_HSPhysics_07_02_light.jpg","alt":"Left panel shows a person in an elevator who shines a light beam on the wall. Beam of light bends down. Elevator is labelled “accelerated up.” Right panel shows same picture, but person is in a room on Earth."},{"sourceId":"fs-id1167067199332","filename":"CNX_HSPhysics_07_02_sun.jpg","relativePath":"media/CNX_HSPhysics_07_02_sun.jpg","alt":"Schematic drawing of sun at left and Earth at right. A person is standing on Earth. Two stars to left of sun. Lines drawn from starts to person’s eyes. Lower star has curved solid line, and upper star has straight dashed line."},{"sourceId":"fs-id1167066791137","filename":"CNX_HSPhysics_07_02_NASA.jpg","relativePath":"media/CNX_HSPhysics_07_02_NASA.jpg","alt":"Photo shows satellite in space."}],"tables":[]},{"uid":"hsphys.ch07.sec02.sub02","title":"Calculations Based on Newton’s Law of Universal Gravitation","summaryVi":null,"paragraphs":["The mass of an object is constant, but its weight varies with the strength of the gravitational field. This means the value of g varies from place to place in the universe. The relationship between force, mass, and acceleration from the second law of motion can be written in terms of g .","In this case, the force is the weight of the object, which is caused by the gravitational attraction of the planet or moon on which the object is located. We can use this expression to compare weights of an object on different moons and planets.","Two equations involving the gravitational constant, G , are often useful. The first is Newton’s equation, \\(\\mathbf{F} = G\\frac{mM}{{r}^{2}}\\) . Several of the values in this equation are either constants or easily obtainable. F is often the weight of an object on the surface of a large object with mass M , which is usually known. The mass of the smaller object, m , is often known, and G is a universal constant with the same value anywhere in the universe. This equation can be used to solve problems involving an object on or orbiting Earth or other massive celestial object. Sometimes it is helpful to equate the right-hand side of the equation to m g and cancel the m on both sides.","The equation \\(\\frac{{r}^{3}}{{T}^{2}} = \\frac{GM}{4{\\pi}^{2}}\\) is also useful for problems involving objects in orbit. Note that there is no need to know the mass of the object. Often, we know the radius r or the period T and want to find the other. If these are both known, we can use the equation to calculate the mass of a planet or star."],"figures":[],"tables":[]},{"uid":"hsphys.ch07.sec02.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["Design an experiment to test whether magnetic force is inversely proportional to the square of distance. Gravitational, magnetic, and electrical fields all act at a distance, but do they all follow the inverse square law? One difference in the forces related to these fields is that gravity is only attractive, but the other two can repel as well. In general, the inverse square law says that force F equals a constant C divided by the distance between objects, d , squared: \\(F = C/{d}^{2}\\) .","Incorporate these materials into your design:\nTwo strong, permanent bar magnets\nA spring scale that can measure small forces\nA short ruler calibrated in millimeters","Use the magnets to study the relationship between attractive force and distance."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch07.sec02.ex01","number":"7.2.1","title":"Change in g","problem":"The value of g on the planet Mars is 3.71 m/s 2 . If you have a mass of 60.0 kg on Earth, what would be your mass on Mars? What would be your weight on Mars?","problemImages":[],"strategy":"Weight equals acceleration due to gravity times mass: \\(\\mathbf{W} = m\\mathbf{g}\\) . An object’s mass is constant. Call acceleration due to gravity on Mars g M and weight on Mars W M .","solution":"Mass on Mars would be the same, 60 kg.\n\\({\\mathbf{W}}_{M} = m{\\mathbf{g}}_{M} = (60.0\\,\\text{kg})(3.71{\\text{m/s}}^{2}) = 223\\,\\text{N}\\)","solutionImages":[],"solutionTables":[],"discussion":"The value of g on any planet depends on the mass of the planet and the distance from its center. If the material below the surface varies from point to point, the value of g will also vary slightly."},{"uid":"hsphys.ch07.sec02.ex02","number":"7.2.2","title":"Earth’s g at the Moon","problem":"Find the acceleration due to Earth’s gravity at the distance of the moon.\n\\(G\\text{= 6}\\text{.67} \\times {\\text{10}}^{\\text{–11}}{\\text{N · m}}^{\\text{2}}{\\text{/kg}}^{\\text{2}}\\text{Earth-moon distance =}3.84\\, \\times {10}^{8}\\text{m}\\text{Earth’s mass =}5.98\\, \\times {10}^{24}\\text{kg}\\)\nExpress the force of gravity in terms of g .\nF = W =  m a =  m g\nCombine with the equation for universal gravitation.\n\\(m\\mathbf{g} = mG\\frac{M}{{r}^{2}}\\)","problemImages":[],"strategy":null,"solution":"Cancel m and substitute.\n\\(\\mathbf{g} = G\\frac{M}{{r}^{2}} = (6.67 \\times {10}^{- 11}\\frac{\\text{N} \\cdot {\\text{m}}^{2}}{{\\text{kg}}^{2}})(\\frac{5.98 \\times {10}^{24}\\text{kg}}{{(3.84 \\times {10}^{8}\\text{m})}^{2}}) = 2.70 \\times {10}^{- 3}{\\text{m/s}}^{2}\\)","solutionImages":[],"solutionTables":[],"discussion":"The value of g for the moon is 1.62 m/s 2 . Comparing this value to the answer, we see that Earth’s gravitational influence on an object on the moon’s surface would be insignificant."}],"snapLabs":[{"uid":"hsphys.ch07.sec02.lab01","title":"Take-Home Experiment: Falling Objects","text":"In this activity you will study the effects of mass and air resistance on the acceleration of falling objects. Make predictions (hypotheses) about the outcome of this experiment. Write them down to compare later with results.\nFour sheets of \\(8\\,\\text{-}\\text{1}/2 \\times 11\\) -inch paper\nProcedure\nTake four identical pieces of paper.\nCrumple one up into a small ball.\nLeave one uncrumpled.\nTake the other two and crumple them up together, so that they make a ball of exactly twice the mass of the other crumpled ball.\nNow compare which ball of paper lands first when dropped simultaneously from the same height.\nCompare crumpled one-paper ball with crumpled two-paper ball.\nCompare crumpled one-paper ball with uncrumpled paper.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch07.sec02.feat01","type":"tip","title":"Tips for Success","text":"When performing calculations using the equations in this chapter, use units of kilograms for mass, meters for distances, newtons for force, and seconds for time.","images":[]}],"summaryPoints":["Newton’s law of universal gravitation provides a mathematical basis for gravitational force and Kepler’s laws of planetary motion.","Einstein’s theory of general relativity shows that gravitational fields change the path of light and warp space and time.","An object’s mass is constant, but its weight changes when acceleration due to gravity, g , changes."],"glossary":[{"term":"Einstein’s theory of general relativity","termVi":"Thuyết tương đối rộng của Einstein","definition":"the theory that gravitational force results from the bending of spacetime by an object’s mass","definitionVi":"Lý thuyết giải thích hấp dẫn là sự uốn cong của không–thời gian bởi khối lượng.","memoryTipVi":"Giải thích hiện tượng bẻ cong ánh sáng và lỗ đen."},{"term":"gravitational constant","termVi":"Hằng số hấp dẫn (G)","definition":"the proportionality constant in Newton’s law of universal gravitation","definitionVi":"Hằng số phổ quát G = 6.674 × 10⁻¹¹ N·m²/kg².","memoryTipVi":"Phân biệt G lớn (hằng số vũ trụ) với g nhỏ (9.8 m/s² trên mặt đất)!"},{"term":"Newton’s universal law of gravitation","termVi":"Định luật Vạn vật hấp dẫn Newton","definition":"states that gravitational force between two objects is directly proportional to the product of their masses and inversely proportional to the square of the distance between them.","definitionVi":"Mọi cặp vật thể hút nhau với lực F = G·m₁m₂ / r².","memoryTipVi":"Tỉ lệ nghịch với BÌNH PHƯƠNG khoảng cách r²."}],"assessments":[{"uid":"hsphys.ch07.sec02.q003","sourceId":"eip-id1166851098005","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Newtons law of universal gravitation explains the paths of what?","images":[],"choices":[{"label":"a","text":"A charged particle"},{"label":"b","text":"A ball rolling on a plane surface"},{"label":"c","text":"A planet moving around the sun"},{"label":"d","text":"A stone tied to a string and whirled at constant speed in a horizontal circle"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q008","sourceId":"fs-id1167065957246","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Saturn’s moon Titan has an orbital period of 15.9 days. If Saturn has a mass of 5.68×10 26 kg, what is the average distance from Titan to the center of Saturn?","images":[],"choices":[{"label":"a","text":"1.22×10 9 m"},{"label":"b","text":"4.26×10 7 m"},{"label":"c","text":"5.25×10 4 km"},{"label":"d","text":"4.26×10 10 km"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q011","sourceId":"eip-id1166848837653","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"The Cavendish experiment marked a milestone in the study of gravity.\nPart A. What important value did the experiment determine?\nPart B. Why was this so difficult in terms of the masses used in the apparatus and the strength of the gravitational force?","images":[],"choices":[{"label":"a","text":"Part A. The experiment measured the acceleration due to gravity, g.\nPart B. Gravity is a very weak force but despite this limitation, Cavendish was able to measure the attraction between very massive objects."},{"label":"b","text":"Part A. The experiment measured the gravitational constant, G.\nPart B. Gravity is a very weak force but, despite this limitation, Cavendish was able to measure the attraction between very massive objects."},{"label":"c","text":"Part A. The experiment measured the acceleration due to gravity, g.\nPart B. Gravity is a very weak force but despite this limitation, Cavendish was able to measure the attraction between less massive objects."},{"label":"d","text":"Part A. The experiment measured the gravitational constant, G.\nPart B. Gravity is a very weak force but despite this limitation, Cavendish was able to measure the attraction between less massive objects."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q012","sourceId":"eip-id1166851229488","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Rhea, with a radius of 7.63×10 5 m, is the second-largest moon of the planet Saturn. If the mass of Rhea is 2.31×10 21 kg, what is the acceleration due to gravity on the surface of this moon?","images":[],"choices":[{"label":"a","text":"2.65×10 -1 m/s"},{"label":"b","text":"2.02×10 5 m/s"},{"label":"c","text":"2.65×10 -1 m/s 2"},{"label":"d","text":"2.02×10 5 m/s 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q013","sourceId":"eip-id1166851451290","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Earth has a mass of 5.971×10 24 kg and a radius of 6.371×10 6 m. Use the data to check the value of the gravitational constant.","images":[],"choices":[{"label":"a","text":"\\(6.66 \\times {10}^{- 11}\\frac{\\text{N} \\cdot \\text{m}}{\\text{k}{\\text{g}}^{2}},\\) it matches the value of the gravitational constant G."},{"label":"b","text":"\\(1.05 \\times {10}^{- 17}\\frac{\\text{N} \\cdot \\text{m}}{\\text{k}{\\text{g}}^{2}},\\) it matches the value of the gravitational constant G."},{"label":"c","text":"\\(6.66 \\times {10}^{- 11}\\frac{\\text{N} \\cdot {\\text{m}}^{2}}{\\text{k}{\\text{g}}^{2}},\\) it matches the value of the gravitational constant G."},{"label":"d","text":"\\(1.05 \\times {10}^{- 17}\\frac{\\text{N} \\cdot {\\text{m}}^{2}}{\\text{k}{\\text{g}}^{2}},\\) it matches the value of the gravitational constant G."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q014","sourceId":"eip-id1166848956950","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"The orbit of the planet Mercury has a period of 88.0 days and an average radius of 5.791×10 10 m. What is the mass of the sun?","images":[],"choices":[{"label":"a","text":"3.43×10 19 kg"},{"label":"b","text":"1.99×10 30 kg"},{"label":"c","text":"2.56×10 29 kg"},{"label":"d","text":"1.48×10 40 kg"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q017","sourceId":"fs-id1167063558407","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What did the Cavendish experiment measure?","images":[],"choices":[{"label":"a","text":"The mass of Earth"},{"label":"b","text":"The gravitational constant"},{"label":"c","text":"Acceleration due to gravity"},{"label":"d","text":"The eccentricity of Earths orbit"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q020","sourceId":"fs-id1167066992525","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Newtons third law of motion says that, for every action force, there is a reaction force equal in magnitude but that acts in the opposite direction. Apply this law to gravitational forces acting between the Washington Monument and Earth.","images":[],"choices":[{"label":"a","text":"The monument is attracted to Earth with a force equal to its weight, and Earth is attracted to the monument with a force equal to Earths weight. The situation can be represented with two force vectors of unequal magnitude and pointing in the same direction."},{"label":"b","text":"The monument is attracted to Earth with a force equal to its weight, and Earth is attracted to the monument with a force equal to Earths weight. The situation can be represented with two force vectors of unequal magnitude but pointing in opposite directions."},{"label":"c","text":"The monument is attracted to Earth with a force equal to its weight, and Earth is attracted to the monument with an equal force. The situation can be represented with two force vectors of equal magnitude and pointing in the same direction."},{"label":"d","text":"The monument is attracted to Earth with a force equal to its weight, and Earth is attracted to the monument with an equal force. The situation can be represented with two force vectors of equal magnitude but pointing in opposite directions."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q021","sourceId":"fs-id1167063519445","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or false—Gravitational force is the attraction of the mass of one object to the mass of another. Light, either as a particle or a wave, has no rest mass. Despite this fact gravity bends a beam of light.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q024","sourceId":"fs-id1167067308224","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"It took scientists a long time to arrive at the understanding of gravity as explained by Galileo and Newton. They were hindered by two ideas that\nseemed like common sense but were serious misconceptions. First was the fact that heavier things fall faster than light things. Second, it was\nbelieved impossible that forces could act at a distance. Explain why these ideas persisted and why they prevented advances.","images":[],"choices":[{"label":"a","text":"Heavier things fall faster than light things if they have less surface area and greater mass density. In the Renaissance and before, forces that\nacted at a distance were considered impossible, so people were skeptical about scientific theories that invoked such forces."},{"label":"b","text":"Heavier things fall faster than light things because they have greater surface area and less mass density. In the Renaissance and before, forces that\nact at a distance were considered impossible, so people were skeptical about scientific theories that invoked such forces."},{"label":"c","text":"Heavier things fall faster than light things because they have less surface area and greater mass density. In the Renaissance and before, forces that\nact at a distance were considered impossible, so people were quick to accept scientific theories that invoked such forces."},{"label":"d","text":"Heavier things fall faster than light things because they have larger surface area and less mass density. In the Renaissance and before, forces that act\nat a distance were considered impossible because of people’s faith in scientific theories."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch07.sec02.q025","sourceId":"fs-id1167066959776","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The masses of Earth and the moon are 5.97×10 24 kg and 7.35×10 22 kg, respectively. The distance from Earth to the moon is 3.80×10 5 km. At what point between the Earth and the moon are the opposing gravitational forces equal? (Use subscripts e and m to represent Earth and moon.)","images":[],"choices":[{"label":"a","text":"3.42×10 5 km from the center of Earth"},{"label":"b","text":"3.80×10 5 km from the center of Earth"},{"label":"c","text":"3.42×10 6 km from the center of Earth"},{"label":"d","text":"3.10×10 7 km from the center of Earth"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":4,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":3,"assessmentCount":11}}],"summary":{"totalSections":3,"totalKeyEquations":9,"totalWorkedExamples":5,"totalSnapLabs":1,"totalGlossaryTerms":9,"totalAssessments":27,"referencedMediaCount":13},"qualityGate":{"passed":true,"checkedUids":46,"errors":[],"warnings":[]}};
